function makeInspector(target) {
  const snapshot = target.status;
  return () => [snapshot, target.status];
}
let job = { status: "open" };
const inspect = makeInspector(job);
job.status = "done";
job = null;
const [before, after] = inspect();
console.log(before);
console.log(after);
console.log(job);
